function molarSolubility(Ksp, a, b){ if(Ksp<=0||a<=0||b<=0) return NaN; return Math.pow(Ksp/(Math.pow(a,a)*Math.pow(b,b)), 1/(a+b)); }
function ksp(concA, concB, a, b){ return Math.pow(concA,a)*Math.pow(concB,b); }
var EXPORTS={molarSolubility:molarSolubility,ksp:ksp};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SolubilityForgePure = EXPORTS; }
